package main

import (
	"bytes"
	"flag"
	"go/ast"
	"go/format"
	"go/token"
	"os"
	"path/filepath"
	"strings"
	"text/template"

	"golang.org/x/tools/go/packages"
)

type packageData struct {
	Package string
	Path    string
	Structs []structData
}

type structData struct {
	Type    string
	Entries []templateEntry
}

type templateEntry struct {
	Name  string
	Field fieldInfo
}

type fieldInfo struct {
	Kind  string
	Type  string
	IsPtr bool
}

const templateStr = `
// Code generated by go generate; DO NOT EDIT.

package {{.Package}}

{{range .Structs}}
func (t *{{.Type}}) Reset() {
	if t == nil {
		return
	}

	{{range .Entries}}
	{{- if .Field.IsPtr}}
	if t.{{.Name}} != nil {
		{{- if eq .Field.Kind "int" "int8" "int16" "int32" "int64" "uint" "uint8" "uint16" "uint32" "uint64"}}
		*t.{{.Name}} = 0
		{{- else if eq .Field.Kind "string"}}
		*t.{{.Name}} = ""
		{{- else if eq .Field.Kind "map"}}
		clear(*t.{{.Name}})
		{{- else if eq .Field.Kind "slice"}}
		*t.{{.Name}} = (*t.{{.Name}})[:0]
		{{- else if eq .Field.Kind "struct"}}
		if resetter, ok := any(t.{{.Name}}).(interface{ Reset() }); ok {
			resetter.Reset()
		}
		{{- else}}
		{{end}}
	}

	{{- else}}
		{{- if eq .Field.Kind "int" "int8" "int16" "int32" "int64" "uint" "uint8" "uint16" "uint32" "uint64"}}
		t.{{.Name}} = 0
		{{- else if eq .Field.Kind "string"}}
		t.{{.Name}} = ""
		{{- else if eq .Field.Kind "bool"}}
		t.{{.Name}} = false
		{{- else if eq .Field.Kind "map"}}
		clear(t.{{.Name}})
		{{- else if eq .Field.Kind "slice"}}
		t.{{.Name}} = t.{{.Name}}[:0]
		{{- else if eq .Field.Kind "struct"}}
		if resetter, ok := any(&t.{{.Name}}).(interface{ Reset() }); ok {
			resetter.Reset()
		}
		{{- else}}
		{{- end}}

		{{- end}}
	{{- end}}
}
{{end}}
`

func main() {
	flag.Parse()

	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedSyntax,
		Tests: false,
	}

	pkgs, err := packages.Load(cfg, "github.com/Albert-Ti/go-musthave-shortener-tpl/...")
	if err != nil {
		panic(err)
	}

	// ключ — уникальный путь пакета, значение — накопленные данные
	packagesMap := map[string]*packageData{}

	for _, pkg := range pkgs {
		for _, file := range pkg.Syntax {
			for _, decl := range file.Decls {
				genDecl, ok := decl.(*ast.GenDecl)
				if !ok || genDecl.Tok != token.TYPE {
					continue
				}
				for _, spec := range genDecl.Specs {
					typeSpec, ok := spec.(*ast.TypeSpec)
					if !ok {
						continue
					}

					doc := genDecl.Doc
					if typeSpec.Doc != nil {
						doc = typeSpec.Doc
					}
					if doc == nil || !strings.Contains(doc.Text(), "generate:reset") {
						continue
					}

					structType, ok := typeSpec.Type.(*ast.StructType)
					if !ok {
						continue
					}

					var entries []templateEntry
					for _, field := range structType.Fields.List {
						for _, name := range field.Names { // ВСЕ имена, не только [0]
							entries = append(entries, templateEntry{
								Name:  name.Name,
								Field: getFieldInfo(field.Type),
							})
						}
					}

					dir := packageDir(pkg)
					pd, ok := packagesMap[dir]
					if !ok {
						pd = &packageData{Package: pkg.Name, Path: dir}
						packagesMap[dir] = pd
					}
					pd.Structs = append(pd.Structs, structData{
						Type:    typeSpec.Name.Name,
						Entries: entries,
					})
				}
			}
		}
	}

	// запись, после полного сбора данных
	tmpl := template.Must(template.New("reset").Parse(templateStr))
	for _, pd := range packagesMap {
		var buf bytes.Buffer
		if err := tmpl.Execute(&buf, pd); err != nil {
			panic(err)
		}
		bufFmt, err := format.Source(buf.Bytes())
		if err != nil {
			panic(err)
		}
		if err := os.WriteFile(pd.Path+"/reset.gen.go", bufFmt, 0644); err != nil {
			panic(err)
		}
	}

}

func packageDir(pkg *packages.Package) string {
	if len(pkg.GoFiles) > 0 {
		return filepath.Dir(pkg.GoFiles[0])
	}
	if len(pkg.CompiledGoFiles) > 0 {
		return filepath.Dir(pkg.CompiledGoFiles[0])
	}
	return ""
}

func getFieldInfo(expr ast.Expr) fieldInfo {
	switch t := expr.(type) {

	case *ast.Ident:
		switch t.Name {
		case "int", "int8", "int16", "int32", "int64",
			"uint", "uint8", "uint16", "uint32", "uint64",
			"string", "bool":
			return fieldInfo{Kind: t.Name}

		default:
			return fieldInfo{
				Kind: "struct",
				Type: t.Name,
			}
		}

	case *ast.ArrayType:
		return fieldInfo{Kind: "slice"}

	case *ast.MapType:
		return fieldInfo{Kind: "map"}

	case *ast.StarExpr:
		info := getFieldInfo(t.X)
		info.IsPtr = true
		return info

	default:
		return fieldInfo{Kind: "unknown"}
	}
}
